package cli

import (
	"context"
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
)

// NewAuthenticatedAPIClient creates an API client targeting api.BaseURL()
// (the data API origin) carrying a token valid for that audience.
//
// Resolution: looks up the core token from the keyring, then either uses
// it directly (single-host setup, or when the core token's `aud` already
// covers api.BaseURL()) or performs an RFC 8693 token exchange against
// the auth host to obtain a token scoped to the data API. Exchanged
// tokens are cached in-memory keyed off the wire-affecting fields of
// the request — see tokenmanager.cacheKey for the precise key shape.
//
// Pass insecureHTTP=true to allow plain HTTP base URLs for local
// development. Both api.BaseURL() and api.AuthBaseURL() are validated:
// the bearer travels to the data host on resource requests, and the
// core token travels to the auth host during the exchange step.
func NewAuthenticatedAPIClient(ctx context.Context, insecureHTTP bool) (*api.Client, error) {
	dataURL, authURL := api.BaseURL(), api.AuthBaseURL()
	if insecureHTTP {
		auth.EnableInsecureHTTP()
	} else {
		if err := api.RequireSecureURL(dataURL); err != nil {
			return nil, fmt.Errorf("base URL check: %w", err)
		}
		if authURL != dataURL {
			if err := api.RequireSecureURL(authURL); err != nil {
				return nil, fmt.Errorf("auth base URL check: %w", err)
			}
		}
	}

	// tokenmanager validates Resource as a strict origin URL; strip any path
	// the operator may have included in ENTIRE_API_BASE_URL before handing
	// it across the package boundary.
	token, err := auth.TokenForResource(ctx, api.OriginOnly(dataURL))
	if err != nil {
		if errors.Is(err, auth.ErrNotLoggedIn) {
			// Wrap the original err (not the sentinel) so any context
			// the tokenmanager attached — keyring backend message,
			// expired-token reason — survives to the caller. The
			// errors.Is(err, auth.ErrNotLoggedIn) chain is preserved
			// because err already wraps the sentinel; replacing it
			// with the bare sentinel would drop that context for
			// zero behavioural gain.
			return nil, fmt.Errorf("not logged in (run 'entire login' first): %w", err)
		}
		return nil, fmt.Errorf("resolve API token: %w", err)
	}

	return api.NewClient(token), nil
}

// Package clusterdiscovery resolves the trusted entire-core URLs that a
// given entire-server cluster will accept JWTs from, by hitting the
// cluster's /.well-known/entire-cluster.json endpoint. Used on the
// cold-boot path where contexts.json doesn't yet bind a cluster to a
// context, so we can tell the user *which* core(s) to log into instead
// of leaving them to guess --base-url.
package clusterdiscovery

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
)

// Path mirrors server/cluster_discovery.go: the cluster advertises which
// entire-core URLs it accepts as JWT issuers.
const Path = "/.well-known/entire-cluster.json"

// DebugFunc is the shape of the optional debug-log callback callers pass
// in. It mirrors fmt.Printf-style formatting so each caller can plug in
// its own env-var-gated logger (e.g. the [git-remote-entire] /
// [entiredb] prefixed debugfs gated by ENTIRE_DEBUG). Pass nil to
// suppress debug output.
type DebugFunc func(format string, args ...any)

// Response is the parsed shape of /.well-known/entire-cluster.json. New
// fields may be added by the server; unknown ones are ignored.
type Response struct {
	CoreURLs []string `json:"core_urls"`
}

// Sentinel errors returned by Discover so callers can branch on the
// failure mode (and surface different operator messages) without
// stringly-typing the diagnosis.
var (
	// ErrUnreachable wraps any transport-level failure dialing the
	// cluster (DNS, connection refused, TLS handshake, timeout). The
	// host might be a typo or a real-but-down cluster — the client
	// can't tell, and operators get the same nudge for both.
	ErrUnreachable = errors.New("cluster unreachable")
	// ErrNoIssuers means the cluster responded HTTP 503 — up but with
	// an empty trusted-issuers configuration. Operator misconfig,
	// not a client problem.
	ErrNoIssuers = errors.New("cluster does not advertise any trusted login servers")
	// ErrNoCoreURLs means the cluster responded HTTP 200 but the JSON
	// carried an empty (or absent) core_urls list. Distinct from
	// ErrNoIssuers because the operator fix is different — the
	// response shape is wrong, rather than the 503 surface being
	// served.
	ErrNoCoreURLs = errors.New("cluster advertises no trusted core URLs")
)

// Discover fetches and parses the cluster's
// /.well-known/entire-cluster.json. On success returns the parsed body
// with a non-empty CoreURLs list. On failure returns one of the
// sentinel errors above (wrapped with context) or a wrapped decode
// error for malformed JSON. Network failures are wrapped under
// ErrUnreachable so the caller can render the "looks unreachable"
// nudge without string-matching.
//
// debugf is optional; nil suppresses debug output.
func Discover(ctx context.Context, clusterHost string, c *http.Client, debugf DebugFunc) (*Response, error) {
	if debugf == nil {
		debugf = func(string, ...any) {}
	}
	url := "https://" + clusterHost + Path
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, fmt.Errorf("build discovery request: %w", err)
	}
	resp, err := c.Do(req)
	if err != nil {
		debugf("cluster discovery: %v", err)
		return nil, fmt.Errorf("%w: %w", ErrUnreachable, err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusServiceUnavailable {
		return nil, ErrNoIssuers
	}
	if resp.StatusCode != http.StatusOK {
		debugf("cluster discovery: HTTP %d from %s", resp.StatusCode, url)
		return nil, fmt.Errorf("HTTP %d from %s", resp.StatusCode, url)
	}
	var body Response
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		debugf("cluster discovery: decode: %v", err)
		return nil, fmt.Errorf("decode %s: %w", url, err)
	}
	if len(body.CoreURLs) == 0 {
		debugf("cluster discovery: no core_urls in response from %s", url)
		return nil, ErrNoCoreURLs
	}
	return &body, nil
}

// RenderLoginHint formats a fatal-ready message describing which
// entire-core URLs an operator can log into to gain credentials for
// clusterHost. The output is stable (one indented URL per line) so
// callers can pattern-match in tests.
func RenderLoginHint(clusterHost string, coreURLs []string) string {
	var b strings.Builder
	fmt.Fprintf(&b, "no auth context for cluster %s. This cluster accepts logins from:\n", clusterHost)
	for _, u := range coreURLs {
		fmt.Fprintf(&b, "  %s\n", u)
	}
	fmt.Fprint(&b, "\nAuthenticate against one of those login servers and re-run your command:\n"+
		"  ENTIRE_AUTH_BASE_URL=<url> entire login\n"+
		"or, if you already have a login there, switch to it with `entire auth use <context>`.")
	return b.String()
}

package clusterdiscovery

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"sort"
	"strings"

	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/entireio/cli/internal/entireclient/discovery"
)

// ResolveContextForCluster picks the local login context to authenticate
// git operations against clusterHost.
//
// It separates two concerns that used to be conflated in a single
// cluster→context binding:
//
//   - Which control plane(s) front the cluster — an objective infra fact.
//     Discovered from the cluster's /.well-known/entire-cluster.json and
//     cached in cluster_cores.json (see discovery.ClusterCoresCache) with
//     a long TTL, since a cluster's home core is near-static. On a cache
//     miss or expiry we re-fetch; if the re-fetch fails we fall back to
//     the stale cached cores rather than break the op.
//
//   - Which of the user's accounts to use — recomputed every call from the
//     live contexts, never persisted. So a user with several accounts is
//     never silently pinned to one identity.
//
// Account selection (selectContext):
//
//  1. If the active context (current_context) is issued by one of the
//     cluster's cores, use it. This is the explicit lever: `entire auth
//     use <name>` chooses the identity for every cluster that context's
//     core fronts.
//  2. Otherwise gather every local context eligible for the cluster (its
//     CoreURL is among the advertised cores):
//     - exactly one  → use it (the common single-account case);
//     - none         → error with the login hint listing the cluster's cores;
//     - more than one → error asking the user to pick with `entire auth use`,
//     rather than silently guessing an account.
//
// We never fall back to an active context whose core does NOT front the
// cluster: the cluster would reject the exchanged token as "unknown
// cluster_host", and silently authenticating a staging identity against a
// prod cluster (or vice versa) is exactly the confusion the /.well-known
// lookup exists to prevent.
//
// debugf is optional; nil suppresses debug output.
func ResolveContextForCluster(ctx context.Context, configDir, cacheDir, clusterHost string, httpClient *http.Client, debugf DebugFunc) (*contexts.Context, error) {
	if debugf == nil {
		debugf = func(string, ...any) {}
	}
	f, err := contexts.Load(configDir)
	if err != nil {
		return nil, fmt.Errorf("load contexts: %w", err)
	}

	coreURLs, err := resolveClusterCores(ctx, cacheDir, clusterHost, httpClient, debugf)
	if err != nil {
		return nil, err
	}

	return selectContext(f, clusterHost, coreURLs, debugf)
}

// ResolveClusterCores returns the trusted control-plane core URLs that
// front clusterHost, using the same cache-then-/.well-known discovery as
// ResolveContextForCluster (see resolveClusterCores). Exported for callers
// that need the cluster's trusted-core set without account selection — e.g.
// the ENTIRE_TOKEN path validates that the env token's audience is one of
// these before exchanging it, so an unverified JWT can't redirect the
// token exchange to an attacker-chosen host.
func ResolveClusterCores(ctx context.Context, cacheDir, clusterHost string, httpClient *http.Client, debugf DebugFunc) ([]string, error) {
	if debugf == nil {
		debugf = func(string, ...any) {}
	}
	return resolveClusterCores(ctx, cacheDir, clusterHost, httpClient, debugf)
}

// resolveClusterCores returns the control-plane core URLs that front
// clusterHost, from cluster_cores.json when fresh, otherwise via a live
// /.well-known fetch (which is then cached). A stale-but-present cache
// entry is used as a fallback when the live fetch fails, so a brief
// cluster outage doesn't break an operation whose cores we already knew.
func resolveClusterCores(ctx context.Context, cacheDir, clusterHost string, httpClient *http.Client, debugf DebugFunc) ([]string, error) {
	cache, err := discovery.LoadClusterCores(cacheDir)
	if err != nil {
		// A cache read problem must not block resolution — discover live.
		debugf("cluster-cores cache load failed: %v; discovering live", err)
		cache = nil
	}

	var stale []string
	if cache != nil {
		if urls, fresh, ok := cache.Get(clusterHost); ok {
			if fresh {
				debugf("cluster %s cores from cache: %v", clusterHost, urls)
				return urls, nil
			}
			stale = urls
			debugf("cluster %s cores cache expired; re-fetching /.well-known", clusterHost)
		}
	}

	body, err := Discover(ctx, clusterHost, httpClient, debugf)
	if err != nil {
		if stale != nil {
			debugf("discovery for %s failed (%v); falling back to stale cached cores %v", clusterHost, err, stale)
			return stale, nil
		}
		return nil, formatDiscoveryError(clusterHost, err)
	}

	if mErr := discovery.ModifyClusterCores(cacheDir, func(c discovery.ClusterCoresCache) error {
		c.Set(clusterHost, body.CoreURLs)
		return nil
	}); mErr != nil {
		// Non-fatal: we resolved the cores, the next call just re-fetches.
		debugf("cluster-cores cache write for %s failed: %v", clusterHost, mErr)
	}
	return body.CoreURLs, nil
}

// selectContext applies the account-selection rules over the cluster's
// advertised cores. See ResolveContextForCluster for the rationale.
func selectContext(f *contexts.File, clusterHost string, coreURLs []string, debugf DebugFunc) (*contexts.Context, error) {
	eligible := eligibleContexts(f, coreURLs)

	// 1. Active context wins when it's eligible for this cluster.
	if current := f.Find(f.CurrentContext); current != nil {
		for _, c := range eligible {
			if c.Name == current.Name {
				debugf("cluster %s -> active context %s", clusterHost, current.Name)
				return current, nil
			}
		}
	}

	// 2. Otherwise the eligible set decides.
	switch len(eligible) {
	case 0:
		return nil, errors.New(RenderLoginHint(clusterHost, coreURLs))
	case 1:
		debugf("cluster %s -> sole eligible context %s", clusterHost, eligible[0].Name)
		return eligible[0], nil
	default:
		return nil, ambiguousContextError(clusterHost, eligible)
	}
}

// eligibleContexts returns the local contexts whose core is among coreURLs,
// de-duplicated by name. Order is unspecified — callers either use the sole
// element or report the whole set, never index [0] as a silent winner.
func eligibleContexts(f *contexts.File, coreURLs []string) []*contexts.Context {
	seen := make(map[string]bool)
	var out []*contexts.Context
	for _, coreURL := range coreURLs {
		for _, c := range f.ContextsForIssuer(coreURL) {
			if !seen[c.Name] {
				seen[c.Name] = true
				out = append(out, c)
			}
		}
	}
	return out
}

// ambiguousContextError is returned when more than one local context could
// authenticate against the cluster and none is active. We refuse to guess —
// the user picks explicitly. Names are sorted so the message is stable.
func ambiguousContextError(clusterHost string, eligible []*contexts.Context) error {
	names := make([]string, len(eligible))
	for i, c := range eligible {
		names[i] = c.Name
	}
	sort.Strings(names)
	return fmt.Errorf("multiple login contexts can authenticate against cluster %s (%s); choose one with `entire auth use <context>` and re-run",
		clusterHost, strings.Join(names, ", "))
}

// formatDiscoveryError turns a Discover error into the message
// operators have always seen at this layer. Kept here (not on the
// sentinels themselves) so the package's errors stay machine-readable
// while the caller-facing strings remain centralised.
func formatDiscoveryError(clusterHost string, err error) error {
	switch {
	case errors.Is(err, ErrUnreachable):
		return fmt.Errorf("%s doesn't look like a cluster, or it is unreachable: %w", clusterHost, err)
	case errors.Is(err, ErrNoIssuers):
		return fmt.Errorf("cluster %s does not advertise any trusted login servers (HTTP 503 from %s); contact the cluster administrator",
			clusterHost, Path)
	case errors.Is(err, ErrNoCoreURLs):
		return fmt.Errorf("cluster %s advertises no trusted core URLs (empty list at %s); contact the cluster administrator",
			clusterHost, Path)
	default:
		return fmt.Errorf("cluster discovery for %s: %w", clusterHost, err)
	}
}

package auth

import (
	"context"
	"fmt"
	"net/url"
	"sync"
	"sync/atomic"

	"github.com/entireio/auth-go/tokenmanager"
	"github.com/entireio/cli/cmd/entire/cli/api"
)

// TokenRequest is the entire-CLI alias of tokenmanager.TokenRequest so
// callers don't have to import the underlying package for the common
// case. The two types are interchangeable.
type TokenRequest = tokenmanager.TokenRequest

// ErrNotLoggedIn re-exports tokenmanager.ErrNotLoggedIn so callers in
// the cli package can errors.Is against it without an extra import.
var ErrNotLoggedIn = tokenmanager.ErrNotLoggedIn

var (
	managerOnce sync.Once
	manager     *tokenmanager.Manager
	errManager  error

	// managerForTest, when non-nil, is returned by defaultManager()
	// instead of constructing the production manager. Guarded by
	// managerTestMu so concurrent tests calling Set/defaultManager
	// don't race. Production code never reads this var.
	managerForTest *tokenmanager.Manager
	managerTestMu  sync.Mutex

	// insecureHTTPOverride records the --insecure-http-auth opt-in.
	// Read once when the package-level manager is built (sync.Once);
	// callers must invoke EnableInsecureHTTP before any TokenForResource
	// call in the same process or the override has no effect. Loopback
	// hosts are always permitted regardless of this flag.
	insecureHTTPOverride atomic.Bool
)

// EnableInsecureHTTP relaxes the package-level manager's HTTPS guard so
// non-loopback http:// resources (and the auth host's STS endpoint) are
// permitted during token resolution. The CLI calls this when the user
// passes --insecure-http-auth to a command that hits the data API on a
// private network (e.g. a split-host local-dev box where both hosts are
// plain HTTP).
//
// Call before any TokenForResource invocation — the manager is built
// lazily on first use and the AllowInsecureHTTP setting is frozen at
// that point.
func EnableInsecureHTTP() {
	insecureHTTPOverride.Store(true)
}

// insecureHTTPEnabled reports whether EnableInsecureHTTP was called. The
// per-context control-plane provider (which bypasses the singleton manager)
// reads this so --insecure-http-auth still relaxes the HTTPS guard for a
// non-loopback http:// core, mirroring the singleton's AllowInsecureHTTP.
func insecureHTTPEnabled() bool {
	return insecureHTTPOverride.Load()
}

// SetManagerForTest installs mgr as the manager returned by
// defaultManager() and returns a cleanup function. Test-only.
func SetManagerForTest(t interface{ Helper() }, mgr *tokenmanager.Manager) func() {
	t.Helper()
	managerTestMu.Lock()
	prev := managerForTest
	managerForTest = mgr
	managerTestMu.Unlock()
	return func() {
		managerTestMu.Lock()
		managerForTest = prev
		managerTestMu.Unlock()
	}
}

// defaultManager returns the package-level Manager built from this
// CLI's identity (current provider, AuthBaseURL, NewStore service
// name). Constructed lazily on first use so any env-var setup
// (ENTIRE_AUTH_BASE_URL, ENTIRE_AUTH_PROVIDER_VERSION) lands before
// construction. sync.Once means later env-var changes within the same
// process are ignored; tests bypass the singleton via SetManagerForTest.
func defaultManager() (*tokenmanager.Manager, error) {
	managerTestMu.Lock()
	override := managerForTest
	managerTestMu.Unlock()
	if override != nil {
		return override, nil
	}
	managerOnce.Do(func() {
		provider := CurrentProvider()
		issuer := api.AuthBaseURL()
		m, err := tokenmanager.New(tokenmanager.Config{
			Issuer:   issuer,
			ClientID: provider.ClientID,
			STSPath:  provider.STSPath,
			// Context-preferring store: the manager reads the active
			// contexts.json login (falling back to the legacy entry) so a
			// single login authenticates every control-plane command.
			Store:     NewContextStore(),
			UserAgent: provider.ClientID,
			Scope:     "cli",
			// Auto-permit loopback http:// for local development. The
			// EnableInsecureHTTP setter adds non-loopback http on top
			// so split-host private-network dev (e.g. http://devbox.internal)
			// works under --insecure-http-auth. Anything else must be
			// https:// — STS ships the user's core token in the request
			// body and would leak in clear otherwise.
			AllowInsecureHTTP: isLoopbackHTTP(issuer) || insecureHTTPOverride.Load(),
		})
		manager = m
		if err != nil {
			errManager = fmt.Errorf("build token manager: %w", err)
		}
	})
	return manager, errManager
}

// TokenForResource returns a bearer token suitable for use against
// resourceBaseURL, performing an RFC 8693 token exchange when the
// stored core token's audience doesn't already cover that resource.
// See tokenmanager.Manager.Token for the full resolution rules.
func TokenForResource(ctx context.Context, resourceBaseURL string) (string, error) {
	m, err := defaultManager()
	if err != nil {
		return "", err
	}
	return m.TokenForResource(ctx, resourceBaseURL) //nolint:wrapcheck // shim returns the lib error verbatim
}

// isLoopbackHTTP reports whether u is an http:// URL pointing at a
// loopback hostname (localhost, 127.0.0.1, ::1). Used to scope the
// "auto-permit insecure HTTP" path on the tokenmanager so production
// misconfigurations fail loudly while loopback-only local-dev flows
// keep working.
func isLoopbackHTTP(rawURL string) bool {
	u, err := url.Parse(rawURL)
	if err != nil || u.Scheme != "http" {
		return false
	}
	host := u.Hostname()
	return host == "localhost" || host == "127.0.0.1" || host == "::1"
}

// Package tokenmanager orchestrates core-token storage and RFC 8693
// token exchanges for an OAuth 2.0 device-flow client.
//
// One Manager per CLI process. Construct it once from the embedding
// CLI's identity (Issuer, ClientID, STSPath, Store) and call
// TokenForResource / Token from data-API call sites.
//
// The package is provider-agnostic: every endpoint, identifier, and
// default value comes from Config. It has no env-var reads, no
// implicit URLs, and no embedded provider tables. Tests inject
// behaviour via SetExchangeForTest / SetNowForTest / SetRefreshForTest /
// SetProcessLockForTest (see testseams.go) rather than via the public
// Config — keeping the STS call out of the caller-controllable surface.
package tokenmanager

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/entireio/auth-go/internal/oauthhttp"
	"github.com/entireio/auth-go/internal/proclock"
	"github.com/entireio/auth-go/refresh"
	"github.com/entireio/auth-go/sts"
	"github.com/entireio/auth-go/tokens"
	"github.com/entireio/auth-go/tokenstore"
)

// DefaultRequestedTokenType is the RFC 8693 §3 URI used when neither
// Config.RequestedTokenType nor TokenRequest.RequestedTokenType is set.
// :access_token is the canonical "give me an OAuth access token" URI;
// the wire format is the server's choice.
//
//nolint:gosec // RFC 8693 token-type URI, not a credential
const DefaultRequestedTokenType = "urn:ietf:params:oauth:token-type:access_token"

// exchangeSkew is the safety margin applied when deciding whether a
// cached exchanged token is still usable. Set conservatively because
// the worst case (re-exchange one extra time per command) is cheap.
const exchangeSkew = 30 * time.Second

// ErrNotLoggedIn is returned by Token / TokenForResource when no core token
// is present in the store, or when a stored token is expired and carries no
// refresh token (the session cannot be silently renewed). Callers can match
// on it to render a "run <login>" message.
var ErrNotLoggedIn = errors.New("not logged in")

// ErrNoSTSPath is returned when an exchange is needed but Config.STSPath
// is empty. Single-host deployments hit the same-host shortcut and never
// reach this; split-host deployments must configure STSPath.
var ErrNoSTSPath = errors.New("token exchange required but Config.STSPath is empty")

// ErrReauthRequired is returned by Token / Refresh when the stored refresh
// token is genuinely revoked or expired (server returned invalid_grant and
// a store re-read confirmed the refresh token was not concurrently
// rotated). Distinct from ErrNotLoggedIn — there was a credential, the
// session simply needs a fresh interactive login. Callers can match on it
// to render "your session expired, log in again".
var ErrReauthRequired = errors.New("reauthentication required")

// ErrNoRefreshPath is returned when a refresh is needed but
// Config.RefreshPath is empty. Mirrors ErrNoSTSPath.
var ErrNoRefreshPath = errors.New("refresh required but Config.RefreshPath is empty")

// Config configures a Manager.
type Config struct {
	// Issuer is the auth host base URL where the device-flow login
	// happened and STS exchanges are POSTed. Required. Doubles as the
	// Store profile key, so a user can be logged into multiple issuers
	// (e.g. regions / staging) without conflict.
	Issuer string

	// ClientID identifies the public client per RFC 6749 §2.3.1 / §3.2.1.
	// Sent on STS exchanges via the client_id form field. Required.
	ClientID string

	// STSPath is the path on Issuer where token-exchange requests are
	// POSTed. Optional: single-host deployments never trigger an
	// exchange (the same-host shortcut wins) so they can leave it
	// empty. When empty and an exchange is attempted, runExchange
	// returns ErrNoSTSPath rather than POSTing to a bogus URL.
	STSPath string

	// RefreshPath is the token-endpoint path where grant_type=refresh_token
	// is POSTed to re-mint the login JWT. Optional: when empty and a
	// refresh is needed, runRefresh returns ErrNoRefreshPath. Often equal
	// to STSPath or the device-flow token path, since servers typically
	// multiplex grants at one /oauth/token.
	RefreshPath string

	// LockDir is the directory holding the cross-process advisory lock
	// file. Empty → os.UserCacheDir()/auth-go (falling back to the system
	// temp dir if the user cache dir is unavailable). The lock file holds
	// no credentials.
	LockDir string

	// Store persists the core token. Required. Use any tokenstore.Store
	// implementation; a per-CLI service name keeps credentials isolated
	// from other CLIs sharing this library.
	Store tokenstore.Store

	// RequestedTokenType is the default RFC 8693 requested_token_type
	// URI. Empty → DefaultRequestedTokenType.
	RequestedTokenType string

	// SubjectTokenType is the RFC 8693 subject_token_type sent on
	// exchanges. Empty → sts.SubjectTokenTypeAccessToken.
	//
	// :access_token is the RFC 8693 §3 URI for "OAuth 2.0 access token
	// issued by the given authorization server" — exactly what the
	// device-code grant returns into Store. The distinction from :jwt
	// matters at the server: zitadel-oidc's STS validator (pkg/op/
	// token_exchange.go's GetTokenIDAndSubjectFromToken) only switches on
	// :access_token / :refresh_token / :id_token; :jwt passes the
	// IsSupported() check upstream but silently falls through to the
	// not-handled branch and surfaces as the (uninformative)
	// "subject_token is invalid" error_description. Other servers
	// generally treat :jwt and :access_token interchangeably for OAuth
	// access tokens, so :access_token is the safer default. A caller who
	// genuinely needs :jwt semantics (RFC 7519 JWT-as-credential rather
	// than OAuth-issued bearer) can set this field explicitly, or bypass
	// tokenmanager and call sts.Client.Exchange directly.
	SubjectTokenType string

	// Scope is the default scope sent on exchanges. Empty → omitted.
	Scope string

	// UserAgent for HTTP requests. Empty → none.
	UserAgent string

	// AllowInsecureHTTP permits exchanges against http:// issuers. Off
	// by default — STS calls ship the user's core token in the request
	// body and must be TLS-protected. Only flip this for local/dev
	// deployments pinned to loopback.
	AllowInsecureHTTP bool

	// Transport overrides the http.RoundTripper used for STS calls.
	// Useful for installing a debug logger or proxy. nil →
	// http.DefaultTransport. Replaces the previous HTTPClient field —
	// see sts.Client.Transport for the security rationale.
	Transport http.RoundTripper
}

func (c Config) validate() error {
	switch {
	case strings.TrimSpace(c.Issuer) == "":
		return errors.New("Config.Issuer is required")
	case strings.TrimSpace(c.ClientID) == "":
		return errors.New("Config.ClientID is required")
	case c.Store == nil:
		return errors.New("Config.Store is required")
	}
	return nil
}

// exchangeFunc / nowFuncType are named so we can hold them in
// atomic.Pointer values. Storing the override behind an
// atomic.Pointer rather than a plain field plus mu lets the hot read
// paths (runExchange, m.now) avoid taking the lock — they were
// previously racing with SetExchangeForTest / SetNowForTest.
type exchangeFunc func(ctx context.Context, req sts.ExchangeRequest) (*tokens.TokenSet, error)
type nowFuncType func() time.Time

// ProcessLock serialises credential mutations (refresh, save, delete)
// across processes. Acquire blocks until the lock is held or ctx is done,
// returning an idempotent release func. On error the returned release func
// is nil and must not be called. The default implementation is a file lock
// (internal/proclock); SetProcessLockForTest swaps a fake.
type ProcessLock interface {
	Acquire(ctx context.Context) (release func(), err error)
}

type refreshFunc func(ctx context.Context, req refresh.Request) (*tokens.TokenSet, error)

// Manager orchestrates core-token storage and STS exchanges. Safe for
// concurrent use.
type Manager struct {
	cfg Config

	mu    sync.Mutex
	cache map[cacheKey]cachedToken

	// Test seams. Set only via SetExchangeForTest / SetNowForTest,
	// both of which require a testing.TB to discourage production
	// callers from synthesising a fake TB to bypass STS. Held behind
	// atomic.Pointer so hot-path reads (runExchange, now) don't race
	// against test setup/teardown.
	exchangeOverride atomic.Pointer[exchangeFunc]
	nowOverride      atomic.Pointer[nowFuncType]

	// refreshMu is the in-process single-flight gate for re-mints. Held
	// across the cross-process lock + grant so concurrent goroutines
	// coalesce onto one re-mint (the second waiter re-reads a fresh token).
	refreshMu sync.Mutex

	// Refresh + process-lock test seams; see SetRefreshForTest /
	// SetProcessLockForTest. Same atomic.Pointer rationale as above.
	refreshOverride atomic.Pointer[refreshFunc]
	lockOverride    atomic.Pointer[ProcessLock]

	lockOnce    sync.Once
	defaultLock ProcessLock
}

// now returns the manager's effective clock. Tests can replace it via
// SetNowForTest; production callers always get time.Now.
func (m *Manager) now() time.Time {
	if p := m.nowOverride.Load(); p != nil {
		return (*p)()
	}
	return time.Now()
}

// New builds a Manager from cfg. Returns an error when required
// fields are missing or Issuer is not an absolute URL.
//
// Issuer is normalized via RFC 3986 §6.2.2 (lowercase scheme/host,
// default-port stripped, no trailing slash) before being used as the
// Store profile key and as the same-host shortcut comparison. Without
// this, two Managers configured with cosmetically-different issuers
// (`https://auth.example.com/` vs `https://auth.example.com`) would
// write to different keyring entries but compare equal for the
// shortcut — one Manager handing out the other's tokens.
func New(cfg Config) (*Manager, error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	// Hold Issuer to the same origin-URL contract as TokenRequest.Resource:
	// userinfo, path, query, fragment all forbidden. The same-host shortcut
	// (Token) byte-compares the normalised Resource against cfg.Issuer; an
	// Issuer that still carries userinfo or a path silently fails that
	// equality even when the caller's Resource is the "same" origin.
	normIssuer, err := oauthhttp.ValidateOriginURL(cfg.Issuer, cfg.AllowInsecureHTTP, "Config.Issuer")
	if err != nil {
		return nil, err //nolint:wrapcheck // pass through with field-named message
	}
	cfg.Issuer = normIssuer
	if cfg.RequestedTokenType == "" {
		cfg.RequestedTokenType = DefaultRequestedTokenType
	}
	if cfg.SubjectTokenType == "" {
		cfg.SubjectTokenType = sts.SubjectTokenTypeAccessToken
	}
	return &Manager{cfg: cfg, cache: map[cacheKey]cachedToken{}}, nil
}

// Issuer returns the configured issuer URL.
func (m *Manager) Issuer() string { return m.cfg.Issuer }

// SaveCoreToken persists the full device-flow token bundle under the
// configured Issuer. Takes the entire tokens.TokenSet (rather than
// just the access token) so RefreshToken, absolute ExpiresAt, and
// Scope survive the round-trip through the keyring — earlier versions
// dropped these fields silently, blocking refresh-token support and
// losing the wire-side expiry hint for opaque tokens.
//
// AccessToken is required (rejected here rather than letting it
// surface as a confusing "Bearer <empty>" later). The tokens.TokenSet
// is otherwise stored verbatim; consumers can read the persisted
// fields back via Store.LoadTokens.
//
// On successful save the in-memory exchange cache is cleared so a
// re-login under a different identity can't return the previous user's
// exchanged tokens. The cacheKey already binds entries to the core
// token's SHA-256 hash, so this is defence-in-depth — see
// TestSaveCoreToken_ClearsExchangeCache.
//
// SaveCoreToken is serialised against in-flight refreshes by acquiring
// refreshMu and the cross-process lock before mutating the store. Without
// this, a refresh whose grant is mid-flight could land its persist after
// a concurrent SaveCoreToken (re-login) and overwrite the new identity
// with the old account's refreshed credentials. Lock ordering matches
// refreshLocked: refreshMu first, then processLock. Can block up to
// ~30s under contention and may return a wrapped lock error. The
// empty-AccessToken check fires before lock acquisition so an obviously
// bad call doesn't touch the filesystem.
func (m *Manager) SaveCoreToken(t tokens.TokenSet) error {
	if t.AccessToken == "" {
		return errors.New("save core token: AccessToken is empty")
	}
	m.refreshMu.Lock()
	defer m.refreshMu.Unlock()
	release, err := m.processLock().Acquire(context.Background())
	if err != nil {
		return fmt.Errorf("save core token: acquire lock: %w", err)
	}
	defer release()
	return m.saveCoreTokenLocked(t)
}

// saveCoreTokenLocked is the lock-free persist path. Caller MUST hold
// refreshMu and the process lock. Used by SaveCoreToken (which acquires
// them) and by persistRefreshed (which runs inside refreshLocked where
// both are already held — a recursive lock attempt here would
// self-deadlock).
//
// The empty-AccessToken check is duplicated here as defence in depth
// because the locked variant is also reachable from persistRefreshed.
func (m *Manager) saveCoreTokenLocked(t tokens.TokenSet) error {
	if t.AccessToken == "" {
		return errors.New("save core token: AccessToken is empty")
	}
	if err := m.cfg.Store.SaveTokens(m.cfg.Issuer, t); err != nil {
		return fmt.Errorf("save core token: %w", err)
	}
	m.mu.Lock()
	m.cache = map[cacheKey]cachedToken{}
	m.mu.Unlock()
	return nil
}

// LookupCoreToken returns the stored core token, or "" if none is
// stored. A nil-return-no-error mirrors how callers expect
// "not-logged-in" to look.
func (m *Manager) LookupCoreToken() (string, error) {
	t, err := m.cfg.Store.LoadTokens(m.cfg.Issuer)
	if errors.Is(err, tokenstore.ErrNotFound) {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("load core token: %w", err)
	}
	return t.AccessToken, nil
}

// Refresh ensures a fresh login JWT, re-minting it from the stored refresh
// token when the current one is expired or near expiry, and returns it.
// It is idempotent when the token is already fresh (a cheap store read, no
// grant). Returns ErrNotLoggedIn when no credential is stored (or an
// expired one carries no refresh token), and ErrReauthRequired when the
// refresh token is revoked/expired.
//
// Callers can use this to warm the session at startup and surface a
// re-login prompt before the first data call rather than mid-request.
//
// Expiry is judged from the login JWT's exp claim. Opaque (non-JWT)
// stored tokens have no client-visible expiry, so they are treated as
// live and never trigger a re-mint — the refresh tier assumes a JWT login
// token (as in the three-tier session model).
func (m *Manager) Refresh(ctx context.Context) (string, error) {
	return m.ensureFreshLogin(ctx)
}

// DeleteCoreToken removes the stored core token and any cached exchanges
// derived from it.
//
// Order matters within the locked region: the keyring delete runs first,
// then the in-memory cache is cleared. If the keyring delete fails the
// cache is left alone — clearing it pre-emptively would create a window
// where the CLI thinks it's logged out (no cache entries) but the keyring
// still hands out the core token to the next process.
//
// DeleteCoreToken is serialised against in-flight refreshes by acquiring
// refreshMu and the cross-process lock before mutating the store. Without
// this, a refresh whose grant is mid-flight could land its persist after
// a concurrent logout and resurrect the deleted session. Lock ordering
// matches refreshLocked: refreshMu first, then processLock. Can block up
// to ~30s under contention and may return a wrapped lock error.
func (m *Manager) DeleteCoreToken() error {
	m.refreshMu.Lock()
	defer m.refreshMu.Unlock()
	release, err := m.processLock().Acquire(context.Background())
	if err != nil {
		return fmt.Errorf("delete core token: acquire lock: %w", err)
	}
	defer release()
	return m.deleteCoreTokenLocked()
}

// deleteCoreTokenLocked is the lock-free delete path. Caller MUST hold
// refreshMu and the process lock.
func (m *Manager) deleteCoreTokenLocked() error {
	if err := m.cfg.Store.DeleteTokens(m.cfg.Issuer); err != nil {
		return fmt.Errorf("delete core token: %w", err)
	}
	m.mu.Lock()
	m.cache = map[cacheKey]cachedToken{}
	m.mu.Unlock()
	return nil
}

// TokenRequest customises one Token call. Empty fields fall back to
// Config defaults.
type TokenRequest struct {
	// Resource is the origin where the bearer will be presented.
	// Required. Used for the same-host shortcut, the JWT-aud shortcut,
	// and as part of the cache key.
	Resource string

	// Audience is the wire-level RFC 8693 audience parameter. Empty →
	// omitted (the AS picks). Independent of Resource — most callers
	// leave Audience empty.
	Audience string

	// RequestedTokenType overrides Config.RequestedTokenType for this
	// call. Empty → Config default.
	RequestedTokenType string

	// Scope overrides Config.Scope for this call. Empty → Config default.
	Scope string
}

// TokenForResource is a convenience for Token using only Resource.
func (m *Manager) TokenForResource(ctx context.Context, resourceBaseURL string) (string, error) {
	return m.Token(ctx, TokenRequest{Resource: resourceBaseURL})
}

// Token resolves a bearer token for use against req.Resource,
// performing an RFC 8693 exchange when needed.
//
// Resolution rules:
//
//  1. No core token in the store → ErrNotLoggedIn.
//  2. Core (login JWT) expired or near expiry → transparently re-mint it
//     from the stored refresh token (see Refresh). No refresh token →
//     ErrNotLoggedIn; refresh token revoked/expired → ErrReauthRequired;
//     Config.RefreshPath unset → ErrNoRefreshPath.
//  3. m.Issuer() == req.Resource (and req.Audience is empty) → use
//     the core token directly. Single-host deployments hit this path.
//  4. Core token's `aud` claim already includes req.Resource → use
//     the core token directly. Multi-audience tokens skip exchange.
//  5. Otherwise → RFC 8693 token exchange.
//
// Successful exchanges are cached in-memory keyed by (core token,
// resource, audience, requested-token-type, scope) until expiry.
func (m *Manager) Token(ctx context.Context, req TokenRequest) (string, error) {
	if strings.TrimSpace(req.Resource) == "" {
		return "", errors.New("TokenRequest.Resource is required")
	}
	normResource, err := oauthhttp.ValidateOriginURL(req.Resource, m.cfg.AllowInsecureHTTP, "TokenRequest.Resource")
	if err != nil {
		return "", err
	}

	core, err := m.ensureFreshLogin(ctx)
	if err != nil {
		return "", err
	}

	// m.cfg.Issuer was normalized at New() time, so no re-normalize here.
	if req.Audience == "" && m.cfg.Issuer == normResource {
		return core, nil
	}
	if req.Audience == "" && coreTokenAudienceIncludes(core, normResource) {
		return core, nil
	}

	resolved := m.resolve(req)
	resolved.Resource = normResource
	// Default Audience to the normalized resource URI. RFC 8693 §2.1
	// treats audience and resource as overlapping ways to identify the
	// target service, but some AS implementations (notably zitadel-OIDC-
	// backed servers — entire-core as of 2026-05) require audience to
	// be populated and reject the request with
	// "invalid_target: audience is required" when only resource is
	// present. Applying the default here, AFTER the same-host and
	// JWT-aud shortcuts above, means single-host deployments still
	// return the core token unchanged without setting audience — only
	// requests that actually go to the STS endpoint get the populated
	// audience. Callers that explicitly set Audience to something
	// different are preserved verbatim.
	if resolved.Audience == "" {
		resolved.Audience = normResource
	}
	key := makeCacheKey(core, resolved, normResource)
	if hit, ok := m.cacheLookup(key); ok {
		return hit, nil
	}

	exchanged, err := m.runExchange(ctx, core, resolved)
	if err != nil {
		return "", err
	}
	m.cacheStore(key, exchanged)
	return exchanged.AccessToken, nil
}

// resolve fills empty TokenRequest fields with Config defaults.
func (m *Manager) resolve(req TokenRequest) TokenRequest {
	if req.RequestedTokenType == "" {
		req.RequestedTokenType = m.cfg.RequestedTokenType
	}
	if req.Scope == "" {
		req.Scope = m.cfg.Scope
	}
	return req
}

// coreTokenExpired reports whether the core token is not currently
// usable: either its `exp` claim is in the past (or within
// exchangeSkew of now) or its `nbf` claim is in the future. JWT
// parse failures (and tokens without an `exp` claim) are reported as
// not-expired so opaque access tokens flow through the rest of the
// resolution rules unchanged.
//
// Applying exchangeSkew here closes a race: a token expiring at
// now+1ms is technically "live", but if we present it to the resource
// (or STS), the request body's TLS handshake + DNS + queue can easily
// push the AS-side validation past the wire-side exp — landing a
// confusing invalid_grant / 401 that triggers a re-login at the worst
// moment. The cost is one fresh login slightly earlier than strictly
// necessary; the cache's exchangeSkew uses the same window so the
// two stay in sync.
//
// Enforcing `nbf` is defence in depth — a token that's not-yet-valid
// shouldn't be presented either. RFC 7519 §4.1.5 requires the
// processor to reject a JWT with `nbf` in the future.
func coreTokenExpired(coreJWT string, now time.Time) bool {
	claims, err := tokens.ParseClaims(coreJWT)
	if err != nil {
		return false
	}
	if !claims.NotBefore.IsZero() && now.Before(claims.NotBefore) {
		return true
	}
	if claims.ExpiresAt.IsZero() {
		return false
	}
	return !now.Add(exchangeSkew).Before(claims.ExpiresAt)
}

// coreTokenAudienceIncludes reports whether the core JWT's `aud` claim
// covers target. target is expected to already be in normalised form;
// aud entries are normalised here so a trailing-slash / case difference
// between the AS and the caller doesn't force a needless STS exchange.
func coreTokenAudienceIncludes(coreJWT, target string) bool {
	claims, err := tokens.ParseClaims(coreJWT)
	if err != nil {
		return false
	}
	for _, aud := range claims.Audience {
		if oauthhttp.NormalizeOriginURL(aud) == target {
			return true
		}
	}
	return false
}

// maxCachedTokenLifetime bounds entries with an unknown wire-side
// expiry. Today this can't happen on the exchange path (sts.Exchange
// rejects non-positive expires_in), but it would still apply if a
// future code path stored a TokenSet without ExpiresAt — capping at 1h
// prevents an indefinitely-cached stale token in that case.
const maxCachedTokenLifetime = time.Hour

// cachedToken is one entry in the per-process exchange cache.
type cachedToken struct {
	accessToken string
	expiresAt   time.Time
	cachedAt    time.Time
}

func (c cachedToken) usable(now time.Time) bool {
	if c.accessToken == "" {
		return false
	}
	if c.expiresAt.IsZero() {
		return now.Sub(c.cachedAt) < maxCachedTokenLifetime
	}
	return now.Add(exchangeSkew).Before(c.expiresAt)
}

// cacheKey is a structurally-keyed exchange-cache key. Using a struct
// rather than a delimiter-joined string sidesteps any chance of two
// distinct (core token, resource, audience, requested-token-type,
// scope) tuples hashing to the same map slot via embedded delimiters
// in any field.
//
// CoreTokenHash is a SHA-256 of the core token rather than the token
// itself: a long-running embedder (daemon, server agent) accumulates
// one cache entry per (Resource, Audience, RequestedTokenType, Scope)
// tuple, so embedding the full token replicates the bearer N times
// across the per-process exchange cache. Memory dumps, crash reports,
// and profile heap snapshots then leak N copies. The hash is a stable
// identifier (collision-resistant for this purpose) that still
// distinguishes between cores from different logins.
type cacheKey struct {
	CoreTokenHash      [sha256.Size]byte
	Resource           string
	Audience           string
	RequestedTokenType string
	Scope              string
}

// makeCacheKey builds a cacheKey from the (resolved) request. Includes
// every wire-affecting field so different combinations don't shadow
// each other. normalizedResource is the caller-supplied Resource after
// normalisation, so https://api.example.com and
// https://api.example.com/ share a single cache entry.
func makeCacheKey(coreToken string, req TokenRequest, normalizedResource string) cacheKey {
	return cacheKey{
		CoreTokenHash:      sha256.Sum256([]byte(coreToken)),
		Resource:           normalizedResource,
		Audience:           req.Audience,
		RequestedTokenType: req.RequestedTokenType,
		Scope:              req.Scope,
	}
}

func (m *Manager) cacheLookup(key cacheKey) (string, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	entry, ok := m.cache[key]
	if !ok {
		return "", false
	}
	if !entry.usable(m.now()) {
		delete(m.cache, key)
		return "", false
	}
	return entry.accessToken, true
}

func (m *Manager) cacheStore(key cacheKey, t *tokens.TokenSet) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.cache[key] = cachedToken{
		accessToken: t.AccessToken,
		expiresAt:   t.ExpiresAt,
		cachedAt:    m.now(),
	}
}

// fileLockPath adapts a derived lock path to ProcessLock via
// internal/proclock. The path field lets tests assert the per-identity
// derivation without importing proclock.
type fileLockPath struct {
	path string
	lock *proclock.FileLock
}

func (f *fileLockPath) Acquire(ctx context.Context) (func(), error) {
	return f.lock.Acquire(ctx) //nolint:wrapcheck // proclock already prefixes "proclock:"
}

// processLock returns the test override if set, else the lazily-built
// default file lock. The lock path is keyed on (ClientID, Issuer) — the
// identity that scopes the stored credential — so unrelated CLIs sharing
// an issuer don't serialise against each other.
func (m *Manager) processLock() ProcessLock {
	if p := m.lockOverride.Load(); p != nil {
		return *p
	}
	m.lockOnce.Do(func() {
		dir := m.cfg.LockDir
		if dir == "" {
			if cache, err := os.UserCacheDir(); err == nil {
				dir = filepath.Join(cache, "auth-go")
			} else {
				dir = filepath.Join(os.TempDir(), "auth-go")
			}
		}
		sum := sha256.Sum256([]byte(m.cfg.ClientID + "\x00" + m.cfg.Issuer))
		path := filepath.Join(dir, hex.EncodeToString(sum[:])+".lock")
		m.defaultLock = &fileLockPath{path: path, lock: proclock.New(path)}
	})
	return m.defaultLock
}

// runRefresh dispatches to the test override (if set) else a freshly built
// refresh.Client pointing at Issuer + RefreshPath. client_id is sent on
// both surfaces (Basic auth via the typed field, form body via Extra),
// matching runExchange — see sts.ExchangeRequest.ClientID for the why.
func (m *Manager) runRefresh(ctx context.Context, refreshToken string) (*tokens.TokenSet, error) {
	req := refresh.Request{
		RefreshToken: refreshToken,
		ClientID:     m.cfg.ClientID,
		Extra:        url.Values{"client_id": {m.cfg.ClientID}},
	}
	if p := m.refreshOverride.Load(); p != nil {
		return (*p)(ctx, req)
	}
	if strings.TrimSpace(m.cfg.RefreshPath) == "" {
		return nil, ErrNoRefreshPath
	}
	client := &refresh.Client{
		Transport:         m.cfg.Transport,
		BaseURL:           m.cfg.Issuer,
		Path:              m.cfg.RefreshPath,
		UserAgent:         m.cfg.UserAgent,
		AllowInsecureHTTP: m.cfg.AllowInsecureHTTP,
	}
	return client.Refresh(ctx, req) //nolint:wrapcheck // refresh.Refresh already prefixes "refresh token:"
}

// loadTokenSet reads the full stored TokenSet for the configured issuer.
// ok=false (with nil error) means no credential is stored; a non-nil error
// is a genuine store failure (never collapsed to "not logged in").
func (m *Manager) loadTokenSet() (set tokens.TokenSet, ok bool, err error) {
	t, err := m.cfg.Store.LoadTokens(m.cfg.Issuer)
	if errors.Is(err, tokenstore.ErrNotFound) {
		return tokens.TokenSet{}, false, nil
	}
	if err != nil {
		return tokens.TokenSet{}, false, fmt.Errorf("load core token: %w", err)
	}
	return t, true, nil
}

// doRefresh runs the refresh_token grant for the currently stored refresh
// token and persists the rotated result. Assumes the caller holds both the
// in-process mutex and the cross-process lock and has already confirmed the
// stored login JWT is expired with a refresh token present.
//
// On invalid_grant it re-reads the store: if the refresh token changed
// (a non-cooperating actor rotated it under us) it retries once with the
// new token; otherwise the family is genuinely dead → ErrReauthRequired.
// Transport and other errors are returned as-is, never as reauth, and
// never delete the stored credential.
func (m *Manager) doRefresh(ctx context.Context) (string, error) {
	set, ok, err := m.loadTokenSet()
	if err != nil {
		return "", err
	}
	if !ok || !set.HasRefresh() {
		return "", ErrNotLoggedIn
	}
	sent := set.RefreshToken

	res, err := m.runRefresh(ctx, sent)
	if err == nil {
		if perr := m.persistRefreshed(set, res); perr != nil {
			return "", perr
		}
		return res.AccessToken, nil
	}
	if !errors.Is(err, refresh.ErrInvalidGrant) {
		return "", err
	}

	// Rotation-race recovery: another actor may have rotated the refresh
	// token between our read and our grant. Re-read; retry once if so.
	cur, ok, rerr := m.loadTokenSet()
	if rerr != nil {
		return "", rerr
	}
	if !ok {
		return "", ErrNotLoggedIn // credential deleted concurrently (e.g. logout)
	}
	if !cur.HasRefresh() {
		return "", ErrNotLoggedIn // refresh token cleared concurrently
	}
	if cur.RefreshToken != sent {
		// A non-cooperating actor rotated the RT under us; retry once.
		res, err = m.runRefresh(ctx, cur.RefreshToken)
		if err == nil {
			if perr := m.persistRefreshed(cur, res); perr != nil {
				return "", perr
			}
			return res.AccessToken, nil
		}
		if !errors.Is(err, refresh.ErrInvalidGrant) {
			return "", err
		}
	}
	return "", ErrReauthRequired
}

// persistRefreshed merges the grant response onto the prior set and saves
// it. A non-rotating server (empty refresh_token / scope in the response)
// must not wipe a still-valid refresh token, so empty fields fall back to
// the prior values. The new login JWT and ExpiresAt always replace.
// SaveCoreToken clears the in-process exchange cache as a side effect, so
// the next Token() re-exchanges against the new login JWT.
func (m *Manager) persistRefreshed(prev tokens.TokenSet, res *tokens.TokenSet) error {
	merged := *res
	if merged.RefreshToken == "" {
		merged.RefreshToken = prev.RefreshToken
	}
	if merged.Scope == "" {
		merged.Scope = prev.Scope
	}
	if merged.TokenType == "" {
		merged.TokenType = prev.TokenType
	}
	// saveCoreTokenLocked (NOT SaveCoreToken) — persistRefreshed runs from
	// inside refreshLocked, which already holds refreshMu + processLock.
	// Re-entering them here would self-deadlock.
	if err := m.saveCoreTokenLocked(merged); err != nil {
		return fmt.Errorf("refresh: persist: %w", err)
	}
	return nil
}

// ensureFreshLogin returns a usable login JWT, transparently re-minting an
// expired one from the stored refresh token. The fast path takes no locks:
// a still-fresh token (the common case) returns immediately. ErrNotLoggedIn
// when no credential is stored or an expired one has no refresh token;
// ErrReauthRequired when the refresh token is revoked/expired.
// The fast path intentionally mirrors freshOrProceed's checks to avoid
// taking refreshMu on the common case of a still-fresh token; keep the two
// in sync if you add an early-exit condition.
func (m *Manager) ensureFreshLogin(ctx context.Context) (string, error) {
	set, ok, err := m.loadTokenSet()
	if err != nil {
		return "", err
	}
	if !ok {
		return "", ErrNotLoggedIn
	}
	// A usable token must be non-empty as well as unexpired. A BYO Store
	// that returns a TokenSet with an empty AccessToken (without
	// ErrNotFound) must not yield an empty bearer — coreTokenExpired("")
	// reports not-expired (parse failure), so guard the empty case here.
	if set.AccessToken != "" && !coreTokenExpired(set.AccessToken, m.now()) {
		return set.AccessToken, nil
	}
	if !set.HasRefresh() {
		return "", ErrNotLoggedIn
	}
	return m.refreshLocked(ctx)
}

// refreshLocked performs the serialize-and-double-check re-mint: the
// in-process mutex coalesces goroutines, the cross-process lock coalesces
// processes, and a store re-read after each gate lets a late waiter return
// the token a peer just minted instead of re-minting.
func (m *Manager) refreshLocked(ctx context.Context) (string, error) {
	m.refreshMu.Lock()
	defer m.refreshMu.Unlock()

	if tok, done, err := m.freshOrProceed(); done {
		return tok, err
	}

	release, err := m.processLock().Acquire(ctx)
	if err != nil {
		return "", fmt.Errorf("refresh: acquire lock: %w", err)
	}
	defer release()

	if tok, done, err := m.freshOrProceed(); done {
		return tok, err
	}

	return m.doRefresh(ctx)
}

// freshOrProceed re-reads the store and reports whether the caller has a
// terminal result. done=true means return (tok, err) directly — the token
// is fresh now, no credential exists, or an expired token has no refresh
// token. done=false means "still expired with a refresh token — proceed to
// the re-mint".
func (m *Manager) freshOrProceed() (string, bool, error) {
	set, ok, err := m.loadTokenSet()
	if err != nil {
		return "", true, err
	}
	if !ok {
		return "", true, ErrNotLoggedIn
	}
	if set.AccessToken != "" && !coreTokenExpired(set.AccessToken, m.now()) {
		return set.AccessToken, true, nil
	}
	if !set.HasRefresh() {
		return "", true, ErrNotLoggedIn
	}
	return "", false, nil
}

// runExchange dispatches to either Config.Exchange (test override) or
// a freshly built sts.Client pointing at m.cfg.Issuer + m.cfg.STSPath.
func (m *Manager) runExchange(ctx context.Context, coreToken string, req TokenRequest) (*tokens.TokenSet, error) {
	stsReq := sts.ExchangeRequest{
		SubjectToken:       coreToken,
		SubjectTokenType:   m.cfg.SubjectTokenType,
		RequestedTokenType: req.RequestedTokenType,
		Audience:           req.Audience,
		Resource:           req.Resource,
		Scope:              req.Scope,
		// Public-client identification per RFC 6749 §3.2.1 (public
		// clients SHOULD include client_id on requests; we go further
		// and ALWAYS include it). Sent on both surfaces simultaneously:
		//   - ClientID populates HTTP Basic Auth — required by servers
		//     that read credentials only from the Basic header on the
		//     token-exchange grant (zitadel-based servers as of
		//     2026-05 are a known example: pkg/op/token_exchange.go
		//     reads only from r.BasicAuth()).
		//   - Extra["client_id"] populates the form body — required by
		//     servers that read credentials from the form, plus it's
		//     the §2.3.1 form for confidential clients.
		// DO NOT delete either line independently. The two surfaces
		// target different server implementations; the test server
		// validates both, so passing tests do not prove production
		// safety against arbitrary auth servers. m.cfg.ClientID is
		// non-empty by Config.validate, so the resulting request has
		// at least one credential surface populated.
		ClientID: m.cfg.ClientID,
		Extra:    url.Values{"client_id": {m.cfg.ClientID}},
	}

	if p := m.exchangeOverride.Load(); p != nil {
		return (*p)(ctx, stsReq)
	}

	if strings.TrimSpace(m.cfg.STSPath) == "" {
		return nil, ErrNoSTSPath
	}

	stsClient := &sts.Client{
		Transport:         m.cfg.Transport,
		BaseURL:           m.cfg.Issuer,
		Path:              m.cfg.STSPath,
		UserAgent:         m.cfg.UserAgent,
		AllowInsecureHTTP: m.cfg.AllowInsecureHTTP,
	}
	return stsClient.Exchange(ctx, stsReq) //nolint:wrapcheck // sts.Exchange already prefixes "token exchange:"
}

package auth

import (
	"context"
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/internal/entireclient/contexts"
)

// ControlPlaneTarget is the resolved login server a control-plane request
// (org/repo/project/grant) should dial, plus the bearer source for it.
//
// CoreURL is an origin (no /api/v1 suffix); the caller appends the API base
// path. TokenSource returns a bearer valid for CoreURL, re-minting silently
// from the stored refresh token when the active context drives resolution.
type ControlPlaneTarget struct {
	CoreURL     string
	TokenSource func(context.Context) (string, error)
}

// ResolveControlPlaneTarget chooses which core the control-plane commands talk
// to and how their bearer is obtained. The control-plane host *is* a core, so
// there is no /.well-known discovery here — the active context already names
// the core. Precedence (matching `auth status`):
//
//  1. the active contexts.json login -> its CoreURL, with a per-context
//     refreshing bearer (silent JWT re-mint). This is what makes
//     `entire auth use <ctx>` retarget the control plane onto that core.
//  2. no active context -> the configured auth origin (ENTIRE_AUTH_BASE_URL or
//     the default) + TokenForResource, the pre-contexts fallback.
//
// ENTIRE_AUTH_BASE_URL is the fallback host, not an override: a token minted
// by the active context's core can't authenticate against a different host, so
// "use the override host but the context's identity" can't succeed. The active
// context always wins when present.
func ResolveControlPlaneTarget() (ControlPlaneTarget, error) {
	c, ok, err := activeContext()
	if err != nil {
		return ControlPlaneTarget{}, err
	}
	if !ok {
		return staticControlPlaneTarget(), nil
	}

	// The refreshing provider keys its own token manager on c.CoreURL as the
	// issuer, so its store reads and STS/refresh both target the right core —
	// the bug the singleton manager (pinned to AuthBaseURL) has when the
	// active context lives on a different core.
	src, err := NewRefreshingLoginProvider(c, nil, insecureHTTPEnabled() || isLoopbackHTTP(c.CoreURL))
	if err != nil {
		return ControlPlaneTarget{}, fmt.Errorf("build token source for context %q: %w", c.Name, err)
	}
	return ControlPlaneTarget{CoreURL: strings.TrimRight(c.CoreURL, "/"), TokenSource: src}, nil
}

// staticControlPlaneTarget is the no-active-context fallback: dial the
// configured auth origin (ENTIRE_AUTH_BASE_URL or the default) and resolve the
// bearer through the singleton manager, which performs an RFC 8693 exchange
// when the stored token's audience doesn't cover the core.
func staticControlPlaneTarget() ControlPlaneTarget {
	base := strings.TrimRight(api.AuthBaseURL(), "/")
	// The exchange's resource must be the bare origin; OriginOnly strips any
	// path/query so the audience the manager keys on matches the server's.
	resource := api.OriginOnly(base)
	return ControlPlaneTarget{
		CoreURL: base,
		TokenSource: func(ctx context.Context) (string, error) {
			return TokenForResource(ctx, resource)
		},
	}
}

// activeContext returns the active contexts.json login and ok=true, or
// ok=false when there is no current context or it carries no CoreURL (an
// unusable pointer we treat as "no active context" rather than dialing an
// empty host).
func activeContext() (c *contexts.Context, ok bool, err error) {
	f, err := contexts.Load(contexts.DefaultConfigDir())
	if err != nil {
		return nil, false, fmt.Errorf("load contexts: %w", err)
	}
	c = f.Find(f.CurrentContext)
	if c == nil || c.CoreURL == "" {
		return nil, false, nil
	}
	return c, true, nil
}

package auth

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/entireio/auth-go/tokenmanager"
	"github.com/entireio/auth-go/tokens"
	authtokenstore "github.com/entireio/auth-go/tokenstore"

	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/entireio/cli/internal/entireclient/tokenstore"
)

// defaultSavedTokenTTL is the encoded keychain expiry used when a refreshed
// token carries no usable ExpiresAt. The server is the real authority; this
// only governs when local readers consider the cached token stale.
const defaultSavedTokenTTL = time.Hour

// contextTokenStore adapts one login context's keyring slots to auth-go's
// tokenstore.Store, so tokenmanager can load, refresh, and persist that
// context's credentials. It is bound to a specific (service, handle) at
// construction and ignores the profile argument: the cluster resolver has
// already chosen exactly one context, so there is no per-issuer account
// ambiguity to resolve here.
//
// Access token lives at `service`/`handle` (with the "|<expiry>" encoding
// the rest of the CLI reads); the refresh token lives raw at
// `service:refresh`/`handle`.
type contextTokenStore struct {
	service string
	handle  string
}

func (s contextTokenStore) LoadTokens(string) (tokens.TokenSet, error) {
	enc, err := tokenstore.Get(s.service, s.handle)
	// Map "no credential stored" to auth-go's sentinel so tokenmanager
	// reports "not logged in" rather than a hard store failure.
	if errors.Is(err, tokenstore.ErrNotFound) || (err == nil && enc == "") {
		return tokens.TokenSet{}, authtokenstore.ErrNotFound
	}
	if err != nil {
		return tokens.TokenSet{}, fmt.Errorf("read access token: %w", err)
	}
	access, expiresAt := tokenstore.DecodeTokenWithExpiration(enc)
	// A missing refresh slot is fine (login predating offline_access) — treat
	// it as no-refresh. Any other store error must surface, not be swallowed:
	// dropping it would silently discard a valid refresh token and force a
	// re-login on what was really a transient keyring/file-store failure.
	refresh, err := tokenstore.Get(tokenstore.RefreshService(s.service), s.handle)
	if err != nil && !errors.Is(err, tokenstore.ErrNotFound) {
		return tokens.TokenSet{}, fmt.Errorf("read refresh token: %w", err)
	}
	return tokens.TokenSet{
		AccessToken:  access,
		RefreshToken: refresh,
		ExpiresAt:    expiresAt,
	}, nil
}

func (s contextTokenStore) SaveTokens(_ string, t tokens.TokenSet) error {
	if t.AccessToken == "" {
		return errors.New("save tokens: empty access token")
	}
	expiresIn := int64(defaultSavedTokenTTL.Seconds())
	if !t.ExpiresAt.IsZero() {
		if secs := int64(time.Until(t.ExpiresAt).Seconds()); secs > 0 {
			expiresIn = secs
		}
	}
	// Persist the rotated refresh token BEFORE the access token. The server
	// single-use-rotates refresh tokens, so a partial write must never leave
	// a fresh access token paired with a stale refresh token: that pairing
	// looks healthy until the access token expires, then the dead refresh
	// token trips invalid_grant/family revocation and forces a re-login.
	// Refresh-first inverts the failure modes: a failed refresh write aborts
	// before touching the access slot (old pair preserved), and a failed
	// access write after a good refresh write self-heals on the next load
	// (the new refresh token re-mints an access token).
	//
	// persistRefreshed carries a still-valid refresh token forward when the
	// server doesn't rotate, so an empty value here means "leave as-is",
	// never "clear".
	if t.RefreshToken != "" {
		if err := tokenstore.Set(tokenstore.RefreshService(s.service), s.handle, t.RefreshToken); err != nil {
			return fmt.Errorf("store refresh token: %w", err)
		}
	}
	if err := tokenstore.Set(s.service, s.handle, tokenstore.EncodeTokenWithExpiration(t.AccessToken, expiresIn)); err != nil {
		return fmt.Errorf("store access token: %w", err)
	}
	return nil
}

func (s contextTokenStore) DeleteTokens(string) error {
	_ = tokenstore.Delete(tokenstore.RefreshService(s.service), s.handle) //nolint:errcheck // best-effort; the access-token delete below is what matters
	if err := tokenstore.Delete(s.service, s.handle); err != nil {
		return fmt.Errorf("delete access token: %w", err)
	}
	return nil
}

// NewRefreshingLoginProvider returns a login-JWT provider (the shape
// repocreds wants) for context c that transparently re-mints an expired
// login JWT from the stored refresh token.
//
// It is backed by auth-go's tokenmanager, which is what makes this safe
// against the server's single-use refresh-token rotation: refreshes are
// serialised across processes (an advisory file lock) and goroutines, the
// store is re-read after locking so a late waiter reuses a peer's freshly
// minted token, and the rotated refresh token is persisted. Without that,
// two concurrent git-remote-entire processes (e.g. a recursive submodule
// fetch) could replay the same single-use token and trip the server's
// reuse detection, revoking the whole family.
//
// Behaviour is a strict superset of the old read-only provider: a still
// valid token is returned with no network call; a context with no refresh
// token (e.g. a login predating offline_access) behaves exactly as before
// — valid token used, expired token surfaces a re-login error.
//
// transport carries the caller's TLS configuration; allowInsecureHTTP
// permits an http:// core for loopback/dev.
func NewRefreshingLoginProvider(c *contexts.Context, transport http.RoundTripper, allowInsecureHTTP bool) (func(context.Context) (string, error), error) {
	if c == nil {
		return nil, errors.New("nil context")
	}
	if c.KeychainService == "" || c.Handle == "" {
		return nil, fmt.Errorf("context %q has no keychain slot", c.Name)
	}
	mgr, err := tokenmanager.New(tokenmanager.Config{
		Issuer:            strings.TrimRight(c.CoreURL, "/"),
		ClientID:          CurrentProvider().ClientID,
		RefreshPath:       CurrentProvider().TokenPath,
		Store:             contextTokenStore{service: c.KeychainService, handle: c.Handle},
		Transport:         transport,
		AllowInsecureHTTP: allowInsecureHTTP,
		UserAgent:         CurrentProvider().ClientID,
	})
	if err != nil {
		return nil, fmt.Errorf("init token manager for context %q: %w", c.Name, err)
	}
	name := c.Name
	coreURL := strings.TrimRight(c.CoreURL, "/")
	// Name the core in the re-login hint so a multi-core user logs back
	// into the right one; matches clusterdiscovery.RenderLoginHint's idiom.
	relogin := fmt.Sprintf("ENTIRE_AUTH_BASE_URL=%s entire login", coreURL)
	return func(ctx context.Context) (string, error) {
		tok, err := mgr.Refresh(ctx)
		switch {
		case errors.Is(err, tokenmanager.ErrReauthRequired):
			return "", fmt.Errorf("login session for %q (%s) expired; run `%s` to re-authenticate", name, coreURL, relogin)
		case errors.Is(err, tokenmanager.ErrNotLoggedIn):
			return "", fmt.Errorf("no usable login for %q (%s); run `%s`", name, coreURL, relogin)
		case err != nil:
			return "", fmt.Errorf("refresh login token: %w", err)
		}
		return tok, nil
	}, nil
}

package auth

import (
	"os"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/api"
)

// ProviderVersionEnvVar overrides the auto-detected provider version.
// Set to "v1" or "v2"; see effectiveProviderVersion for resolution.
// Read once at process startup via CurrentProvider.
const ProviderVersionEnvVar = "ENTIRE_AUTH_PROVIDER_VERSION"

// Provider captures the per-surface bits of OAuth wiring.
//
// STSPath is the RFC 8693 token-exchange endpoint. v1 is the legacy
// single-host surface where the auth and data API live at the same
// origin; the same-host shortcut in tokenmanager.Token always wins and
// STS is never invoked, so v1.STSPath is left empty. v2 exposes a
// dedicated STS path because it's used in split-host deployments
// (e.g. us.auth.partial.to mints, partial.to consumes).
type Provider struct {
	ClientID       string
	DeviceCodePath string
	TokenPath      string
	STSPath        string
}

var providers = map[string]Provider{
	"v1": { //nolint:gosec // OAuth client_id and endpoint paths, not credentials
		ClientID:       "entire-cli",
		DeviceCodePath: "/oauth/device/code",
		TokenPath:      "/oauth/token",
	},
	"v2": { //nolint:gosec // OAuth client_id and endpoint paths, not credentials
		// Matches an OIDC-standard auth server's discovery doc — confirmed
		// against us.auth.partial.to's /.well-known/openid-configuration.
		// Device authorization, token poll, and RFC 8693 exchange all hit
		// the standard endpoints; grant_type differentiates token vs
		// exchange at the shared /oauth/token endpoint.
		ClientID:       "entire-cli",
		DeviceCodePath: "/device_authorization",
		TokenPath:      "/oauth/token",
		STSPath:        "/oauth/token",
	},
}

// resolveProvider returns the Provider matching version. Defaulting
// (rather than erroring) on unrecognised values keeps old binaries safe
// if a future v3 ever lands. Pure function — no env reads — so unit
// tests can exercise the routing table without env-var gymnastics.
func resolveProvider(version string) Provider {
	switch strings.TrimSpace(version) {
	case "v2":
		return providers["v2"]
	default:
		return providers["v1"]
	}
}

// effectiveProviderVersion resolves the version string fed into
// resolveProvider. Order: explicit env var > split-host auto-detect > v1.
//
// The CLI is split-host by default (us.auth.entire.io for auth, entire.io
// for data), so unset env vars take the auto-detect branch and resolve to
// v2 — the OIDC surface us.auth.entire.io serves. v1 only kicks in when a
// caller explicitly collapses both origins onto a single non-OIDC host.
func effectiveProviderVersion() string {
	if v := strings.TrimSpace(os.Getenv(ProviderVersionEnvVar)); v != "" {
		return v
	}
	if api.IsSplitHost() {
		return "v2"
	}
	return "v1"
}

var (
	providerOnce     sync.Once
	resolvedProvider Provider

	// providerForTest, when non-nil, short-circuits CurrentProvider so
	// tests can install a specific Provider without racing the
	// process-wide sync.Once (which freezes the first observation
	// forever). Mutated only via SetProviderForTest. Production code
	// never reads this var.
	providerForTest *Provider
	providerTestMu  sync.Mutex
)

// CurrentProvider returns the active Provider for this process.
// Resolution freezes on the first call (env vars must be set before
// then). Tests bypass the singleton via SetProviderForTest.
func CurrentProvider() Provider {
	providerTestMu.Lock()
	override := providerForTest
	providerTestMu.Unlock()
	if override != nil {
		return *override
	}
	providerOnce.Do(func() {
		resolvedProvider = resolveProvider(effectiveProviderVersion())
	})
	return resolvedProvider
}

// SetProviderForTest installs p as the Provider returned by
// CurrentProvider for the duration of the test, and registers a
// t.Cleanup to remove the override. Test-only.
//
// Takes a tiny interface rather than *testing.T so production builds
// don't import testing.
func SetProviderForTest(t interface {
	Helper()
	Cleanup(f func())
}, p Provider) {
	t.Helper()
	providerTestMu.Lock()
	prev := providerForTest
	providerForTest = &p
	providerTestMu.Unlock()
	t.Cleanup(func() {
		providerTestMu.Lock()
		providerForTest = prev
		providerTestMu.Unlock()
	})
}

