package search

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"
)

const apiTimeout = 30 * time.Second

// DefaultServiceURL is the production search service URL.
const DefaultServiceURL = "https://entire.io"

// WildcardQuery is the query string used when only filters are provided (no search terms).
const WildcardQuery = "*"

// AllReposFilter is the inline repo filter value that disables repo scoping.
const AllReposFilter = "*"

// MaxLimit is the maximum number of results the search API will return per request.
const MaxLimit = 200

// Meta contains search ranking metadata for a result.
type Meta struct {
	MatchType string  `json:"matchType"`
	Score     float64 `json:"score"`
	Snippet   string  `json:"snippet,omitempty"`
}

// CheckpointResult represents a checkpoint returned by the search service.
type CheckpointResult struct {
	ID             string   `json:"id"`
	Prompt         string   `json:"prompt"`
	CommitMessage  *string  `json:"commitMessage"`
	CommitSHA      *string  `json:"commitSha"`
	Branch         string   `json:"branch"`
	Org            string   `json:"org"`
	Repo           string   `json:"repo"`
	Author         string   `json:"author"`
	AuthorUsername *string  `json:"authorUsername"`
	CreatedAt      string   `json:"createdAt"`
	FilesTouched   []string `json:"filesTouched"`
}

// Result wraps a search result with its type and ranking metadata.
type Result struct {
	Type string           `json:"type"`
	Data CheckpointResult `json:"data"`
	Meta Meta             `json:"searchMeta"`
}

// Response is the search service response.
type Response struct {
	Results []Result `json:"results"`
	Total   int      `json:"total"`
	Page    int      `json:"page"`
	Error   string   `json:"error,omitempty"`
}

// Config holds the configuration for a search request.
type Config struct {
	ServiceURL  string // Base URL of the search service
	GitHubToken string
	Owner       string
	Repo        string
	Repos       []string
	Query       string
	Limit       int
	Author      string // Filter by author name
	Date        string // Filter by time period: "week" or "month"
	Branch      string // Filter by branch name
	Page        int    // 1-based page number (0 means omit, API defaults to 1)
}

// HasFilters reports whether any filter fields are set on the config.
func (c Config) HasFilters() bool {
	return c.Author != "" || c.Date != "" || c.Branch != "" || len(c.Repos) > 0
}

// ParsedInput holds the parsed query and optional filters extracted from search input.
type ParsedInput struct {
	Query  string
	Author string
	Date   string
	Branch string
	Repos  []string
}

// ParseSearchInput extracts filter prefixes from raw input.
// Supports quoted values for single-value filters, for example: author:"alice smith".
// Remaining tokens become the query.
func ParseSearchInput(raw string) ParsedInput {
	var p ParsedInput
	var queryParts []string

	tokens := tokenizeInput(raw)
	for _, tok := range tokens {
		switch {
		case strings.HasPrefix(tok, "author:"):
			p.Author = strings.Trim(tok[len("author:"):], "\"")
		case strings.HasPrefix(tok, "date:"):
			p.Date = strings.Trim(tok[len("date:"):], "\"")
		case strings.HasPrefix(tok, "branch:"):
			p.Branch = strings.Trim(tok[len("branch:"):], "\"")
		case strings.HasPrefix(tok, "repo:"):
			p.Repos = appendUnique(p.Repos, parseListFilter(strings.TrimPrefix(tok, "repo:"))...)
		default:
			queryParts = append(queryParts, tok)
		}
	}

	p.Query = strings.Join(queryParts, " ")
	return p
}

// tokenizeInput splits input on whitespace but respects quoted values after filter prefixes.
// Example: `author:"alice smith" fix bug` → ["author:\"alice smith\"", "fix", "bug"]
func tokenizeInput(s string) []string {
	var tokens []string
	i := 0
	s = strings.TrimSpace(s)
	for i < len(s) {
		// Skip whitespace
		for i < len(s) && s[i] == ' ' {
			i++
		}
		if i >= len(s) {
			break
		}

		start := i

		// Look ahead: is this a prefix:"quoted" token?
		if colonIdx := strings.Index(s[i:], ":\""); colonIdx >= 0 && !strings.Contains(s[i:i+colonIdx], " ") {
			// Found prefix:" — scan to closing quote
			quoteStart := i + colonIdx + 2
			endQuote := strings.IndexByte(s[quoteStart:], '"')
			if endQuote >= 0 {
				i = quoteStart + endQuote + 1
				tokens = append(tokens, s[start:i])
				continue
			}
		}

		// Regular token: advance to next space
		for i < len(s) && s[i] != ' ' {
			i++
		}
		tokens = append(tokens, s[start:i])
	}
	return tokens
}

func parseListFilter(raw string) []string {
	if raw == "" {
		return nil
	}

	parts := strings.Split(raw, ",")
	values := make([]string, 0, len(parts))
	for _, part := range parts {
		value := strings.Trim(strings.TrimSpace(part), "\"")
		if value == "" {
			continue
		}
		values = append(values, value)
	}

	return values
}

// ValidateRepoFilters ensures repo filters match backend semantics.
func ValidateRepoFilters(repos []string) error {
	if len(repos) > 1 {
		return errors.New("only one explicit repo filter is currently supported")
	}
	if len(repos) == 1 && !isValidRepoFilter(repos[0]) {
		return fmt.Errorf(
			"invalid repo filter %q: expected owner/name or *; if you meant all repos, quote the asterisk: --repo '*'",
			repos[0],
		)
	}
	return nil
}

func isValidRepoFilter(repo string) bool {
	if repo == AllReposFilter {
		return true
	}
	if strings.Contains(repo, " ") {
		return false
	}
	parts := strings.Split(repo, "/")
	return len(parts) == 2 && parts[0] != "" && parts[1] != ""
}

func appendUnique(existing []string, values ...string) []string {
	if len(values) == 0 {
		return existing
	}

	seen := make(map[string]struct{}, len(existing)+len(values))
	for _, value := range existing {
		seen[value] = struct{}{}
	}
	for _, value := range values {
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		existing = append(existing, value)
	}

	return existing
}

var httpClient = &http.Client{}

// Search calls the search service to perform a hybrid search.
func Search(ctx context.Context, cfg Config) (*Response, error) {
	ctx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()

	serviceURL := cfg.ServiceURL
	if serviceURL == "" {
		serviceURL = DefaultServiceURL
	}

	u, err := url.Parse(serviceURL)
	if err != nil {
		return nil, fmt.Errorf("parsing service URL: %w", err)
	}
	u.Path = "/search/v1/search"

	q := u.Query()
	q.Set("q", cfg.Query)
	if err := ValidateRepoFilters(cfg.Repos); err != nil {
		return nil, err
	}
	allRepos := len(cfg.Repos) == 1 && cfg.Repos[0] == AllReposFilter
	if len(cfg.Repos) > 0 && !allRepos {
		for _, repo := range cfg.Repos {
			q.Add("repo", repo)
		}
	} else if len(cfg.Repos) == 0 && cfg.Owner != "" && cfg.Repo != "" {
		q.Set("repo", cfg.Owner+"/"+cfg.Repo)
	}
	q.Set("types", "checkpoints")
	if cfg.Limit > 0 {
		q.Set("limit", strconv.Itoa(cfg.Limit))
	}
	if cfg.Author != "" {
		q.Set("author", cfg.Author)
	}
	if cfg.Date != "" {
		q.Set("date", cfg.Date)
	}
	if cfg.Branch != "" {
		q.Set("branch", cfg.Branch)
	}
	if cfg.Page > 0 {
		q.Set("page", strconv.Itoa(cfg.Page))
	}
	u.RawQuery = q.Encode()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return nil, fmt.Errorf("creating request: %w", err)
	}
	req.Header.Set("Authorization", "Bearer "+cfg.GitHubToken)
	req.Header.Set("User-Agent", "entire-cli")

	resp, err := httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("calling search service: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("reading response: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		var errResp struct {
			Error string `json:"error"`
		}
		if json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
			return nil, fmt.Errorf("search service error (%d): %s", resp.StatusCode, errResp.Error)
		}
		return nil, fmt.Errorf("search service returned %d: %s", resp.StatusCode, string(body))
	}

	var result Response
	if err := json.Unmarshal(body, &result); err != nil {
		return nil, fmt.Errorf("unexpected response from search service: %s", string(body))
	}

	if result.Error != "" {
		return nil, fmt.Errorf("search service error: %s", result.Error)
	}

	return &result, nil
}

package api

import (
	"errors"
	"fmt"
	"net/url"
	"os"
	"strings"
)

// ErrInsecureHTTP is returned when the base URL uses HTTP without an explicit opt-in.
var ErrInsecureHTTP = errors.New("refusing to use insecure http:// base URL for authentication (use --insecure-http-auth to override)")

const (
	// DefaultBaseURL is the production Entire API origin.
	DefaultBaseURL = "https://entire.io"

	// DefaultAuthBaseURL is the production Entire auth origin (device flow,
	// auth-token management, keyring key). The CLI is split-host by default:
	// auth on us.auth.entire.io, data on entire.io.
	DefaultAuthBaseURL = "https://us.auth.entire.io"

	// BaseURLEnvVar overrides the Entire API origin for local development.
	BaseURLEnvVar = "ENTIRE_API_BASE_URL"

	// AuthBaseURLEnvVar overrides only the auth/login origin (device flow,
	// auth-tokens management, keyring key). Falls back to DefaultAuthBaseURL
	// when unset; local-dev and single-host deployments must set this
	// alongside ENTIRE_API_BASE_URL.
	AuthBaseURLEnvVar = "ENTIRE_AUTH_BASE_URL"

	schemeHTTP  = "http"
	schemeHTTPS = "https"
)

// BaseURL returns the effective Entire API base URL.
// ENTIRE_API_BASE_URL takes precedence over the production default.
func BaseURL() string {
	if raw := strings.TrimSpace(os.Getenv(BaseURLEnvVar)); raw != "" {
		return normalizeBaseURL(raw)
	}

	return DefaultBaseURL
}

// AuthBaseURL returns the origin used for the device-flow login, auth-token
// management endpoints, and the keyring key under which the bearer token is
// stored. ENTIRE_AUTH_BASE_URL takes precedence; otherwise it falls back to
// DefaultAuthBaseURL (split-host by default).
//
// The result is canonicalised — lowercased scheme/host, default port stripped,
// path/query/fragment dropped, trailing slash collapsed — so the value that
// flows into store.SaveToken keys matches what tokenmanager.New emits after
// its own NormalizeOriginURL pass. Without this, a user setting
// ENTIRE_AUTH_BASE_URL=https://AUTH.example.com:443/ would log in successfully
// (saved under the raw form) but every subsequent data-API command would
// resolve "not logged in" because the manager probes under the normalised
// "https://auth.example.com".
func AuthBaseURL() string {
	raw := strings.TrimSpace(os.Getenv(AuthBaseURLEnvVar))
	if raw == "" {
		raw = DefaultAuthBaseURL
	}
	return NormalizeOriginURL(raw)
}

// IsSplitHost reports whether the CLI is configured for split-host —
// i.e. ENTIRE_AUTH_BASE_URL points at a different origin than the data
// API. Both sides are canonicalised via NormalizeOriginURL before
// comparison: AuthBaseURL already does this internally, but BaseURL
// only trims whitespace and a trailing slash, so a cosmetically-
// different ENTIRE_API_BASE_URL (uppercase host, explicit :443, path
// suffix) would otherwise look split when it isn't.
func IsSplitHost() bool {
	return AuthBaseURL() != NormalizeOriginURL(BaseURL())
}

// ResolveURL joins an API-relative path against the effective base URL.
func ResolveURL(path string) (string, error) {
	return ResolveURLFromBase(BaseURL(), path)
}

// ResolveURLFromBase joins an API-relative path against an explicit base URL.
// Only http and https schemes are accepted.
func ResolveURLFromBase(baseURL, path string) (string, error) {
	base, err := url.Parse(baseURL)
	if err != nil {
		return "", fmt.Errorf("parse base URL: %w", err)
	}

	if base.Scheme != schemeHTTP && base.Scheme != schemeHTTPS {
		return "", fmt.Errorf("unsupported base URL scheme %q (must be http or https)", base.Scheme)
	}

	rel, err := url.Parse(path)
	if err != nil {
		return "", fmt.Errorf("parse path: %w", err)
	}

	return base.ResolveReference(rel).String(), nil
}

// RequireSecureURL returns ErrInsecureHTTP if the base URL uses the http scheme.
// Call this before making authenticated requests unless --insecure-http-auth is set.
func RequireSecureURL(baseURL string) error {
	u, err := url.Parse(baseURL)
	if err != nil {
		return fmt.Errorf("parse base URL: %w", err)
	}

	if u.Scheme == schemeHTTP {
		return ErrInsecureHTTP
	}

	return nil
}

func normalizeBaseURL(raw string) string {
	return strings.TrimRight(strings.TrimSpace(raw), "/")
}

// NormalizeOriginURL canonicalises an origin URL the same way auth-go's
// tokenmanager does internally: lowercase scheme/host, default port stripped
// (80 for http, 443 for https), path/query/fragment dropped, trailing slash
// collapsed. On parse failure, raw is returned unchanged so non-URL audience
// values still compare byte-for-byte.
//
// Mirrors auth-go's internal/oauthhttp.NormalizeOriginURL so the value the
// CLI hands to the manager as Issuer survives the manager's own normalisation
// pass byte-for-byte — see AuthBaseURL.
func NormalizeOriginURL(raw string) string {
	trimmed := strings.TrimSpace(raw)
	u, err := url.Parse(trimmed)
	if err != nil || u.Scheme == "" || u.Host == "" {
		return trimmed
	}
	scheme := strings.ToLower(u.Scheme)
	hostname := strings.ToLower(u.Hostname())
	port := u.Port()
	dropPort := port == "" ||
		(scheme == schemeHTTP && port == "80") ||
		(scheme == schemeHTTPS && port == "443")

	out := url.URL{Scheme: scheme}
	switch {
	case dropPort && strings.Contains(hostname, ":"):
		out.Host = "[" + hostname + "]"
	case dropPort:
		out.Host = hostname
	case strings.Contains(hostname, ":"):
		out.Host = "[" + hostname + "]:" + port
	default:
		out.Host = hostname + ":" + port
	}
	return out.String()
}

// OriginOnly is a backwards-compatible alias for NormalizeOriginURL.
// Callers reading raw URLs (e.g. ENTIRE_SEARCH_URL) and feeding them into
// tokenmanager.TokenRequest.Resource use this to strip path/query/fragment
// before the lib's stricter origin-only validator runs.
func OriginOnly(raw string) string {
	return NormalizeOriginURL(raw)
}

