64	// exclusive flock — load, mutate, and write all happen with the lock held.
65	// Use this for any read-modify-write sequence; LoadCache followed by
66	// SaveCache releases the lock between them and races concurrent writers
67	// (e.g. two parallel clone/fetch/push processes updating nodes.json), losing
68	// each other's entries.
69	func ModifyCache(cacheDir string, fn func(ClusterCache) error) error {
70		return modifyCacheFile(cacheDir, cacheFileName, readCacheNoLock, writeCacheNoLock, fn)
71	}
