84	// package: nodes.json, cluster_cores.json) ---
85	
86	// withCacheFileLock ensures cacheDir exists, takes the exclusive flock for
87	// the named cache file, and runs fn with the file's path.
88	func withCacheFileLock(cacheDir, fileName string, fn func(path string) error) error {
89		if err := os.MkdirAll(cacheDir, 0700); err != nil {
90			return fmt.Errorf("create cache dir: %w", err)
91		}
92		path := filepath.Join(cacheDir, fileName)
93		unlock, err := lockCache(path)
94		if err != nil {
95			return err
96		}
97		defer unlock()
98		return fn(path)
99	}
