101	// modifyCacheFile runs a load → mutate → write cycle for one cache file with
102	// the file's flock held throughout, so concurrent processes filling the same
103	// entry don't clobber each other.
104	func modifyCacheFile[T any](cacheDir, fileName string, read func(string) (T, error), write func(string, T) error, fn func(T) error) error {
105		return withCacheFileLock(cacheDir, fileName, func(path string) error {
106			c, err := read(path)
107			if err != nil {
108				return err
109			}
110			if err := fn(c); err != nil {
111				return err
112			}
113			return write(path, c)
114		})
