117	func lockCache(path string) (func(), error) {
118		fl := flock.New(path + ".lock")
119		ctx, cancel := context.WithTimeout(context.Background(), lockTimeout)
120		defer cancel()
121	
122		locked, err := fl.TryLockContext(ctx, lockRetry)
123		if err != nil {
124			return nil, fmt.Errorf("acquire cache lock: %w", err)
125		}
126		if !locked {
127			return nil, errors.New("timeout acquiring cache lock")
128		}
129		return func() { _ = fl.Unlock() }, nil //nolint:errcheck // unlock failure is non-fatal
130	}
