132	// loadCacheFile reads path and unmarshals it into dst. A missing file leaves
133	// dst at its caller-initialized (empty) value; a corrupt file resets dst via
134	// newEmpty so a damaged cache self-heals on the next write instead of wedging
135	// callers. Returns an error only on a genuine read failure. Returning error
136	// (rather than the cache value itself) keeps this generic helper off the
137	// ireturn linter while still sharing the read/unmarshal logic across caches.
138	func loadCacheFile[T any](path string, dst *T, newEmpty func() T) error {
139		data, exists, err := readCacheBytes(path)
140		if err != nil {
141			return err
142		}
143		if !exists {
144			return nil
145		}
146		if json.Unmarshal(data, dst) != nil {
147			*dst = newEmpty() // corrupt → start fresh
148		}
149		return nil
150	}
