package server

import (
	"encoding/json"
	"log/slog"
	"net/http"
	"slices"
	"strings"

	"entire.io/slogutil"
)

// clusterConfigPath is the well-known path the cluster serves so a
// fresh client without a matching contexts.json entry can discover
// which entire-core URLs are trusted as JWT issuers and prompt the
// user to log into one. git-remote-entire calls this on the cold-clone
// path (see cmd/git-remote-entire/cluster_discovery.go).
const clusterConfigPath = "/.well-known/entire-cluster.json"

// extractTrustedCoreURLs picks the URL-shaped audiences out of
// TrustedAudiences and returns them deduplicated and sorted. Each
// per-issuer audience list typically contains the issuer's base URL
// alongside non-URL audience names (e.g. "service:entiredb"); the URLs
// are what clients hit for STS token exchange.
func extractTrustedCoreURLs(trustedAudiences map[string][]string) []string {
	seen := make(map[string]struct{}, len(trustedAudiences))
	for _, auds := range trustedAudiences {
		for _, aud := range auds {
			if !strings.HasPrefix(aud, "https://") && !strings.HasPrefix(aud, "http://") {
				continue
			}
			seen[strings.TrimRight(aud, "/")] = struct{}{}
		}
	}
	if len(seen) == 0 {
		return nil
	}
	out := make([]string, 0, len(seen))
	for u := range seen {
		out = append(out, u)
	}
	slices.Sort(out)
	return out
}

// handleClusterDiscovery answers GET /.well-known/entire-cluster.json.
// Returns the regional entire-core URLs this cluster trusts as JWT
// issuers (extracted from ENTIRE_TRUSTED_AUDIENCES) plus the cluster's
// entry domain. 503 when no URL-shaped audiences are configured —
// clients surface that as a misconfiguration error rather than
// silently guessing.
//
// git-remote-entire calls this on cold clone when contexts.json has
// no matching entry, so the user can be told which entire-core to log
// into instead of guessing a --base-url.
func (s *HTTPServer) handleClusterDiscovery(w http.ResponseWriter, r *http.Request) {
	if len(s.cfg.trustedCoreURLs) == 0 {
		http.Error(w, "cluster discovery not configured", http.StatusServiceUnavailable)
		return
	}
	resp := struct {
		CoreURLs      []string `json:"core_urls"`
		ClusterDomain string   `json:"cluster_domain,omitempty"`
	}{
		CoreURLs:      s.cfg.trustedCoreURLs,
		ClusterDomain: s.cfg.clusterDomain,
	}
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "public, max-age=300")
	if err := json.NewEncoder(w).Encode(resp); err != nil {
		slogutil.Error(r.Context(), "Failed to encode cluster discovery response", slog.Any("error", err))
	}
}
