import { createRemoteJWKSet, errors as joseErrors, jwtVerify } from "jose"

import { recordSpanError } from "./telemetry"

// Scope `validateCoreJwt` requires on inbound bearer JWTs. The paired
// entiredb change (validateAPIAccessExchange in core/authn/oidcop/
// token_exchange.go) stamps this scope onto the api-access JWT minted
// from a login JWT via the STS exchange. Until that ships, every real
// entire-core token still carries `scope=openid` and this gate rejects
// — same broken state as today's "reject any scope" check, no worse.
export const ENTIRE_API_ACCESS_SCOPE = "entire:api-access"

export interface CoreJwtPrincipal {
  userId: string
  coreAccountId: string
  handle: string
  scope: string
}

export interface CoreBearerConfig {
  baseUrl: string
  audience: string
}

export interface CoreBearerEnv {
  ENTIRE_CORE_BEARER_ENABLED?: string
  ENTIRE_CORE_BASE_URL?: string
  ENTIRE_CORE_JWT_AUDIENCE?: string
}

export type FindUserByGithubId = (githubId: number) => Promise<{ id: string } | null>

interface JwksEntry {
  baseUrl: string
  jwks: ReturnType<typeof createRemoteJWKSet>
}

export class CoreJwtUnavailableError extends Error {
  readonly code = "ERR_CORE_JWKS_UNAVAILABLE"

  constructor(readonly reason: string) {
    super("Authentication service unavailable")
    this.name = "CoreJwtUnavailableError"
  }
}

export function isCoreJwtUnavailableError(err: unknown): boolean {
  return (
    typeof err === "object" &&
    err !== null &&
    "code" in err &&
    err.code === "ERR_CORE_JWKS_UNAVAILABLE"
  )
}

let cached: JwksEntry | null = null
const emittedConfigWarnings = new Set<string>()

function getJWKS(baseUrl: string): ReturnType<typeof createRemoteJWKSet> {
  if (cached?.baseUrl === baseUrl) return cached.jwks
  const jwks = createRemoteJWKSet(new URL(`${baseUrl}/.well-known/jwks.json`), {
    cooldownDuration: 30_000,
    cacheMaxAge: 10 * 60_000,
  })
  cached = { baseUrl, jwks }
  return jwks
}

// Clears module state for tests that swap JWKS keys or assert one-shot warnings.
export function _resetJwksCacheForTests(): void {
  cached = null
  emittedConfigWarnings.clear()
}

export function getCoreBearerConfig(env: CoreBearerEnv): CoreBearerConfig | null {
  if (env.ENTIRE_CORE_BEARER_ENABLED !== "true") return null
  if (!env.ENTIRE_CORE_BASE_URL) {
    warnConfigOnce(
      "missing_base_url",
      "ENTIRE_CORE_BASE_URL is required when bearer auth is enabled",
    )
    return null
  }
  if (!env.ENTIRE_CORE_JWT_AUDIENCE) {
    warnConfigOnce(
      "missing_audience",
      "ENTIRE_CORE_JWT_AUDIENCE is required when bearer auth is enabled",
    )
    return null
  }

  const baseUrl = normalizeBaseUrl(env.ENTIRE_CORE_BASE_URL)
  if (!baseUrl || !isAcceptableJwksOrigin(baseUrl)) {
    reportCoreJwtError(
      "error",
      "insecure_base_url_rejected",
      "ENTIRE_CORE_BASE_URL must be https:// (loopback http allowed for local dev)",
      true,
    )
    return null
  }

  return {
    baseUrl,
    audience: env.ENTIRE_CORE_JWT_AUDIENCE,
  }
}

function warnConfigOnce(key: string, message: string): void {
  if (emittedConfigWarnings.has(key)) return
  emittedConfigWarnings.add(key)
  console.warn("[core-jwt] bearer_misconfigured:", message)
  recordSpanError(new Error(`[core-jwt] bearer_misconfigured: ${message}`))
}

function normalizeBaseUrl(rawUrl: string): string | null {
  try {
    return new URL(rawUrl).toString().replace(/\/+$/, "")
  } catch {
    return null
  }
}

// JWKS material is the trust root for every JWT we accept. Plaintext fetch
// would let a network attacker swap keys mid-flight. Allow http only on
// loopback so local dev against a self-hosted entire-core still works.
function isAcceptableJwksOrigin(rawUrl: string): boolean {
  let url: URL
  try {
    url = new URL(rawUrl)
  } catch {
    return false
  }
  const loopbackHosts = new Set(["localhost", "127.0.0.1", "[::1]", "::1"])
  if (url.protocol === "https:") return true
  if (url.protocol === "http:" && loopbackHosts.has(url.hostname)) {
    return true
  }
  return false
}

const ACCOUNT_PREFIX = "account:"

export async function validateCoreJwt(
  token: string,
  config: CoreBearerConfig,
  findUserByGithubId: FindUserByGithubId,
): Promise<CoreJwtPrincipal | null> {
  let payload: import("jose").JWTPayload
  try {
    const result = await jwtVerify(token, getJWKS(config.baseUrl), {
      // Algorithm pinning keeps the protected header from selecting weaker verification.
      algorithms: ["EdDSA"],
      issuer: config.baseUrl,
      audience: config.audience,
    })
    payload = result.payload
  } catch (err) {
    if (!(err instanceof joseErrors.JOSEError)) {
      // Programmer error (bad URL, etc.) — surface, don't pretend it's auth.
      reportCoreJwtError(
        "error",
        "unexpected_verify_error",
        err instanceof Error ? err.message : String(err),
        true,
      )
      throw err
    }
    const operationalError = logJoseError(err)
    if (operationalError) throw operationalError
    return null
  }

  const sub = typeof payload.sub === "string" ? payload.sub : null
  const coreAccountId = !sub
    ? ""
    : sub.startsWith(ACCOUNT_PREFIX)
      ? sub.slice(ACCOUNT_PREFIX.length)
      : sub
  const provider = payload.provider
  const providerUserId = payload.provider_user_id

  if (
    !coreAccountId ||
    provider !== "github" ||
    typeof providerUserId !== "string" ||
    !/^\d+$/.test(providerUserId)
  ) {
    const details = JSON.stringify({
      hasSub: typeof payload.sub === "string",
      provider: typeof provider === "string" ? provider : typeof provider,
      providerUserIdType: typeof providerUserId,
    })
    reportCoreJwtError("warn", "payload_contract_violation", details, true)
    return null
  }

  const githubId = Number(providerUserId)
  if (!Number.isSafeInteger(githubId)) {
    reportCoreJwtError("warn", "payload_contract_violation", "provider_user_id out of range", true)
    return null
  }

  // Positive scope assertion: require entire:api-access. Defensive in
  // lieu of per-route scope enforcement — once routes pin their own
  // required scopes this gate becomes redundant, but until then it
  // protects against the silent-privilege-escalation case the previous
  // "reject any scope" check was guarding (treating a scoped token as
  // full bearer when entire-core starts issuing scoped JWTs for our
  // audience).
  //
  // Rejecting tokens without entire:api-access covers:
  //   - Broad login JWTs (e.g. aud=us.auth.partial.to in staging, scope
  //     carrying entire:session). These would already fail jose's
  //     audience check above; pinning scope as well means future
  //     audience drift can't silently widen privilege.
  //   - Tokens from any future entire-core grant that *isn't* api-access.
  //
  // The paired entiredb change (validateAPIAccessExchange) stamps this
  // scope on the api-access JWT it mints. Until that ships, every real
  // entire-core token carries scope=openid and gets rejected here.
  const scopeClaim = typeof payload.scope === "string" ? payload.scope : ""
  const scopes = scopeClaim.split(/\s+/).filter(Boolean)
  if (!scopes.includes(ENTIRE_API_ACCESS_SCOPE)) {
    reportCoreJwtError("warn", "scope_missing_api_access", scopeClaim, true)
    return null
  }

  const user = await findUserByGithubId(githubId)
  if (!user) return null

  const handle = typeof payload.handle === "string" ? payload.handle : ""

  return {
    userId: user.id,
    coreAccountId,
    handle,
    scope: scopeClaim,
  }
}

function logJoseError(err: import("jose").errors.JOSEError): CoreJwtUnavailableError | null {
  const { code, name } = err
  switch (code) {
    case "ERR_JWT_EXPIRED":
      // Benign and high-volume — no log.
      return null
    case "ERR_JWS_SIGNATURE_VERIFICATION_FAILED":
      console.warn("[core-jwt] signature_invalid:", code)
      return null
    case "ERR_JOSE_ALG_NOT_ALLOWED":
      console.warn("[core-jwt] alg_not_allowed:", code)
      return null
    case "ERR_JWT_CLAIM_VALIDATION_FAILED": {
      const claim = (err as joseErrors.JWTClaimValidationFailed).claim
      const reason = (err as joseErrors.JWTClaimValidationFailed).reason
      console.warn("[core-jwt] claim_mismatch:", JSON.stringify({ claim, reason }))
      return null
    }
    case "ERR_JWKS_NO_MATCHING_KEY":
      console.warn("[core-jwt] jwks_key_not_found:", code, name)
      return null
    case "ERR_JWKS_INVALID":
    case "ERR_JWKS_TIMEOUT":
      reportCoreJwtError("error", "jwks_failure", `${code} ${name}`, true)
      return new CoreJwtUnavailableError(code)
    default:
      console.warn("[core-jwt] verify_failed:", code, name)
      return null
  }
}

function reportCoreJwtError(
  level: "warn" | "error",
  event: string,
  detail: string,
  recordError: boolean,
): void {
  const message = `[core-jwt] ${event}:`
  console[level](message, detail)
  if (!recordError) return
  // Telemetry must never break authentication. recordSpanError
  // ultimately calls span.recordException + span.setStatus on the OTEL
  // SDK; a misconfigured SDK can throw, which would bubble through
  // validateCoreJwt's call site and surface as a 500 from
  // requireBearerAuth (which only catches CoreJwtUnavailableError).
  // Swallow + log so a legitimate auth rejection never escalates to a
  // server error.
  try {
    recordSpanError(new Error(`${message} ${detail}`))
  } catch (telemetryErr) {
    console.warn("[core-jwt] telemetry_emit_failed:", telemetryErr)
  }
}

